function initCandlestickCharts(){if(!window.echarts)return;document.querySelectorAll(".candlestick-module").forEach(e=>{if(e.dataset.initialized==="true")return;const t=e.querySelector(".candlestick-chart"),n=e.querySelector('script[type="application/json"]');if(!t||!n)return;const s=JSON.parse(n.textContent),o=window.echarts.init(t),i=s.map(e=>[e[1],e[4],e[3],e[2]]);o.setOption({backgroundColor:"transparent",grid:{left:58,right:20,top:18,bottom:42},tooltip:{trigger:"axis"},xAxis:{type:"category",data:s.map(e=>e[0]),axisLabel:{color:"#8998a9"},axisLine:{lineStyle:{color:"#1d3041"}}},yAxis:{type:"value",axisLabel:{color:"#8998a9"},splitLine:{lineStyle:{color:"#1d3041"}}},series:[{type:"candlestick",data:i,itemStyle:{color:"#00f5d4",color0:"#ff6b6b",borderColor:"#00f5d4",borderColor0:"#ff6b6b"}}]}),window.addEventListener("resize",()=>o.resize()),e.dataset.initialized="true"})}window.DualityModules=window.DualityModules||{},window.DualityModules.initCandlestickCharts=initCandlestickCharts